    currentPassword: z.string().min(1, 'Required'),
    newPassword: z.string().min(6, 'Must be at least 6 characters'),
    confirmPassword: z.string(),
  })
  .refine((data) => data.newPassword === data.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  });

export type ChangePasswordInput = z.infer<typeof changePasswordInputSchema>;

export const changePassword = ({
  data,
}: {
  data: ChangePasswordInput;
}): Promise<void> => {
  return api.patch('/users/change-password', data);
};

type UseChangePasswordOptions = {
  mutationConfig?: MutationConfig<typeof changePassword>;
};

export const useChangePassword = ({
  mutationConfig,
}: UseChangePasswordOptions = {}) => {
  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      useNotifications.getState().addNotification({
        type: 'success',
        title: 'Password Updated',
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: changePassword,
  });
};

import { KeyRound } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Input } from '@/components/ui/form';

import {
  changePasswordInputSchema,
  useChangePassword,
} from '../api/change-password';

export const ChangePassword = () => {
  const changePasswordMutation = useChangePassword();

  return (
    <FormDrawer
      isDone={changePasswordMutation.isSuccess}
      triggerButton={
        <Button icon={<KeyRound className="size-4" />} size="sm">
          Change Password
        </Button>
      }
      title="Change Password"
      submitButton={
        <Button
          form="change-password"
          type="submit"
          size="sm"
          isLoading={changePasswordMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="change-password"
        onSubmit={(values) => {
          changePasswordMutation.mutate({ data: values });
        }}
        schema={changePasswordInputSchema}
      >
        {({ register, formState }) => (
          <>
            <Input
              label="Current Password"
              type="password"
              error={formState.errors['currentPassword']}
              registration={register('currentPassword')}
            />
            <Input
              label="New Password"
              type="password"
              error={formState.errors['newPassword']}
              registration={register('newPassword')}
            />
            <Input
              label="Confirm New Password"
              type="password"
              error={formState.errors['confirmPassword']}
              registration={register('confirmPassword')}
            />
          </>
        )}
      </Form>
    </FormDrawer>
  );
};

